VIEWS=[('toys-shopper', "__goto('toys');__setClock(null,11);__run(2);P.x-=Math.sin(P.yaw)*2.4;P.z-=Math.cos(P.yaw)*2.4;[P.x,P.z]=collideXZ(P.x,P.z,.3,CUR);P.pitch=innerWidth<innerHeight?-.08:.02;for(const q of PET_ACTORS)if(q.loc===CUR.id){q.x=P.x+Math.sin(P.yaw)*1.4;q.z=P.z+Math.cos(P.yaw)*1.4;[q.x,q.z]=collideXZ(q.x,q.z,.3,CUR);}for(const q of SHOPPERS)if(q.L===CUR&&Math.hypot(q.x-P.x,q.z-P.z)<3.4){let best=-1,bd=0;q.cfg.spots.forEach((sp,j)=>{const x=CUR.ox+sp[0],z=CUR.oz+sp[1],d=Math.hypot(x-P.x,z-P.z);if(d>bd&&!SHOPPERS.some(o=>o!==q&&o.L===CUR&&(o.i===j||o.next===j||Math.hypot(o.x-x,o.z-z)<1.2))){bd=d;best=j;}});if(best>=0){const sp=q.cfg.spots[best];q.i=best;q.next=-1;q.x=CUR.ox+sp[0];q.z=CUR.oz+sp[1];q.wait=9;}};(()=>{const q=SHOPPERS.find(q=>q.L===CUR);if(!q)return 'none';const f=P.yaw;q.x=P.x-Math.sin(f)*.6-Math.cos(f)*.55;q.z=P.z-Math.cos(f)*.6+Math.sin(f)*.55;let bi=0,bd=-1;q.cfg.spots.forEach((sp,j)=>{const d=Math.hypot(CUR.ox+sp[0]-q.x,CUR.oz+sp[1]-q.z);if(d>bd){bd=d;bi=j;}});q.next=bi;q.wait=0;return [+q.x.toFixed(2),+q.z.toFixed(2),bi];})()"), ('toys-report', 'SHOPPERS.filter(q=>q.L===CUR).map(q=>[+Math.hypot(q.x-camera.position.x,q.z-camera.position.z).toFixed(2),q.next,+q.wait.toFixed(1),q.g.visible])')]
